// src/voice-tutor/tokens.js
var TOKEN_TTL_S = 600;
var TOKENS_PER_MINUTE = 20;
var CARTESIA_WS = "wss://api.cartesia.ai/tts/websocket";
var CARTESIA_VERSION = "2026-08-14";
var reply = (status, body) => ({ status, body });
var dayStartIso = (now) => {
  const d = new Date(now);
  d.setUTCHours(0, 0, 0, 0);
  return d.toISOString();
};
async function mintToken({ user, body, db, settings, keys = {}, fetch: f, now = Date.now() }) {
  if (!user?.id) return reply(401, { error: "Sign in first." });
  if (!settings?.enabled) return reply(403, { error: "The live tutor is switched off." });
  const email = String(user.email || "").toLowerCase();
  if (!email || !settings.allowlist.includes(email)) return reply(403, { error: "Voice is for adult test accounts only until parent consent is built (milestone 5)." });
  const sid = String(body?.session_id || "");
  if (!/^[A-Za-z0-9-]{8,64}$/.test(sid)) return reply(400, { error: "No session." });
  let childKey = user.id;
  if (body?.child_id) {
    const child = await db.getChild(String(body.child_id));
    if (!child || child.parent_id !== user.id) return reply(403, { error: "That child is not on this account." });
    childKey = `${user.id}_c${child.id}`;
  }
  let spent;
  try {
    spent = await db.spend({ sessionId: sid, childKey, since: dayStartIso(now) });
  } catch {
    return reply(503, { error: "Voice cannot check its spending (has the voice_tutor_usage migration been run?)." });
  }
  const cap = capCheck({ sessionUsd: spent.session, dayUsd: spent.day }, settings);
  if (!cap.ok) return reply(402, { error: "This lesson has used its allowance for today.", reason: cap.reason });
  const recent = await db.countTokens({ userId: user.id, since: new Date(now - 6e4).toISOString() });
  if (recent >= TOKENS_PER_MINUTE) return reply(429, { error: "Too many voice requests. Wait a moment." });
  const key = keys.cartesia;
  if (!key) return reply(503, { error: "Voice is not set up (CARTESIA_API_KEY is missing)." });
  let out;
  try {
    const r = await f("https://api.cartesia.ai/access-token", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Cartesia-Version": CARTESIA_VERSION, "Content-Type": "application/json" },
      body: JSON.stringify({ grants: { tts: true, stt: true }, expires_in: TOKEN_TTL_S })
    });
    if (!r.ok) throw new Error(`cartesia ${r.status}`);
    const j = await r.json();
    if (!j?.token) throw new Error("cartesia gave no token");
    out = { token: j.token, expires_in: TOKEN_TTL_S, version: CARTESIA_VERSION, url: CARTESIA_WS, model: settings.ttsModel, voice: settings.ttsVoice, speed: settings.ttsSpeed, emotion: settings.ttsEmotion === "none" ? null : settings.ttsEmotion, sample_rate: settings.ttsSampleRate };
  } catch (e) {
    console.error("voice token", String(e?.message || e).slice(0, 200));
    return reply(502, { error: "The voice service did not answer. Please type for now." });
  }
  await db.recordUsage({ user_id: user.id, child_key: childKey, session_id: sid, model: "cartesia", cost_usd: 0, guard: ["token-voice"], dropped_steps: 0 });
  return reply(200, out);
}

// scripts/voice-tutor-token.template.ts
var cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type"
};
var json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json", "Cache-Control": "no-store" } });
var dbFor = (admin) => ({
  async getChild(id) {
    if (!/^[0-9a-f-]{36}$/i.test(id)) return null;
    const { data } = await admin.from("children").select("id, parent_id").eq("id", id).maybeSingle();
    return data || null;
  },
  async spend({ sessionId, childKey, since }) {
    const [a, b] = await Promise.all([
      admin.from("voice_tutor_usage").select("cost_usd").eq("session_id", sessionId),
      admin.from("voice_tutor_usage").select("cost_usd").eq("child_key", childKey).gte("created_at", since)
    ]);
    if (a.error || b.error) throw new Error((a.error || b.error).message);
    const sum = (r) => (r.data || []).reduce((s, x) => s + Number(x.cost_usd || 0), 0);
    return { session: sum(a), day: sum(b) };
  },
  async countTokens({ userId, since }) {
    const { count } = await admin.from("voice_tutor_usage").select("id", { count: "exact", head: true }).eq("user_id", userId).gte("created_at", since).contains("guard", ["token-voice"]);
    return count ?? 0;
  },
  async recordUsage(row) {
    const { error } = await admin.from("voice_tutor_usage").insert(row);
    if (error) console.error("voice_tutor_usage insert", error);
  }
});
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  try {
    const asUser = createClient(Deno.env.get("SUPABASE_URL"), Deno.env.get("SUPABASE_ANON_KEY"), {
      global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } }
    });
    const { data: { user } } = await asUser.auth.getUser((req.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "").trim());
    if (!user) return json({ error: "Sign in first." }, 401);
    const admin = createClient(Deno.env.get("SUPABASE_URL"), Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"));
    const out = await mintToken({
      user,
      body: await req.json().catch(() => ({})),
      db: dbFor(admin),
      settings: settingsFrom((k) => Deno.env.get(k)),
      keys: { cartesia: Deno.env.get("CARTESIA_API_KEY") },
      fetch
    });
    return json(out.body, out.status);
  } catch (e) {
    console.error(e);
    return json({ error: "Voice is not available just now. Please type." }, 500);
  }
});
